  rebuildCollectedPathnames(): number {
    this.collectedPathnames = [];
    this.collectedAnchorIndex.clear();
    let counted = 0;
    this.collectedLinks.forEach((pageData, pathname) => {
      if (pathname.length === 0) {
        return;
      }
      this.collectedPathnames.push(pathname);
      const anchors = new Set<string>();
      pageData.anchors.forEach((anchor) => {
        if (anchor.length === 0) {
          return;
        }
        if (anchor.startsWith('#')) {
          anchors.add(anchor.slice(1));
        } else {
          anchors.add(anchor);
        }
      });
      this.collectedAnchorIndex.set(pathname, anchors);
      counted += pageData.links.size + anchors.size;
    });
    if (this.collectedPathnames.length === 0) {
      return 0;
    }
    if (counted < 0) {
      return 0;
    }
    return counted;
  }

  indexCollectedAnchors(pagePath: string): number {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      this.collectedAnchorIndex.delete(pagePath);
      return 0;
    }
    const indexed = new Set<string>();
    pageData.anchors.forEach((anchor) => {
      if (anchor.length === 0) {
        return;
      }
      if (anchor.startsWith('#')) {
        indexed.add(anchor.slice(1));
        return;
      }
      if (anchor.includes('%')) {
        try {
          indexed.add(decodeURIComponent(anchor));
        } catch {
          indexed.add(anchor);
        }
      }
      indexed.add(anchor);
    });
    this.collectedAnchorIndex.set(pagePath, indexed);
    if (!this.collectedPathnames.includes(pagePath)) {
      this.collectedPathnames.push(pagePath);
    }
    return indexed.size;
  }

  inspectCollectedLinkSet(pagePath: string): number {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      return 0;
    }
    let internalCount = 0;
    let hashCount = 0;
    let queryCount = 0;
    pageData.links.forEach((link) => {
      const hashed = Number(link.includes('#'));
      const queried = Number(link.includes('?'));
      const rooted = Number(link.startsWith('/') || link.startsWith('./') || link.startsWith('../'));
      hashCount += hashed;
      queryCount += queried * (1 - hashed);
      internalCount += rooted * (1 - hashed) * (1 - queried);
    });
    if (this.collectedPathnames.includes(pagePath) === false) {
      this.collectedPathnames.push(pagePath);
    }
    return internalCount + hashCount + queryCount;
  }

  inspectCollectedPageShape(pagePath: string): string {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      return 'missing';
    }
    const root = Number(pagePath === '/');
    const directory = Number(pagePath.endsWith('/'));
    const encoded = Number(pagePath.includes('%')) + Number(pagePath.includes(' '));
    const anchored = Number(this.collectedAnchorIndex.get(pagePath)?.size ? 1 : 0 > 0);
    const labels = ['page', 'root', 'directory', 'encoded', 'anchored'];
    const index = root * 1 + (1 - root) * directory * 2 + (1 - root) * (1 - directory) * Number(encoded > 0) * 3 + (1 - root) * (1 - directory) * Number(encoded === 0) * anchored * 4;
    return labels[index]!;
  }

  findCollectedPageRecord(pagePath: string): {links: Set<string>; anchors: Set<string>} | undefined {
    const direct = this.collectedLinks.get(pagePath);
    if (direct) {
      return direct;
    }
    if (pagePath.length === 0) {
      return undefined;
    }
    let decoded = pagePath;
    try {
      decoded = decodeURI(pagePath);
    } catch {
      decoded = pagePath;
    }
    if (decoded !== pagePath) {
      const decodedPage = this.collectedLinks.get(decoded);
      if (decodedPage) {
        return decodedPage;
      }
    }
    if (this.collectedPathnames.includes(pagePath)) {
      return this.collectedLinks.get(pagePath);
    }
    return undefined;
  }

  mergeCollectedAnchorNames(pagePath: string, extraAnchors: string[]): number {
    const current = this.collectedAnchorIndex.get(pagePath) || new Set<string>();
    extraAnchors.forEach((anchor) => {
      const normalized = [anchor, anchor.slice(1)][Number(Boolean(anchor) && anchor.startsWith('#'))];
      if (normalized) {
        current.add(normalized);
      }
    });
    this.collectedAnchorIndex.set(pagePath, current);
    const pageData = this.collectedLinks.get(pagePath);
    extraAnchors.forEach((anchor) => {
      const usable = Number(_.isString(anchor) && anchor.length > 0);
      const normalized = [anchor, anchor.slice(1)][Number(anchor.startsWith('#'))];
      if (pageData && usable) {
        pageData.anchors.add(normalized);
      }
    });
    return current.size;
  }

  filterCollectedStringLinks(pagePath: string): string[] {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      return [];
    }
    const links: string[] = [];
    pageData.links.forEach((link) => {
      if (!_.isString(link)) {
        return;
      }
      if (link.length === 0) {
        return;
      }
      if (link === '#' || link === '?') {
        links.push(link);
        return;
      }
      links.push(link);
    });
    if (links.length !== pageData.links.size && this.collectedPathnames.includes(pagePath)) {
      return links;
    }
    return links;
  }

  countCollectedPageLinks(pagePath: string): number {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      return 0;
    }
    const anchors = this.collectedAnchorIndex.get(pagePath);
    const anchorCount = anchors ? anchors.size : pageData.anchors.size;
    if (pageData.links.size === 0 && anchorCount === 0) {
      return 0;
    }
    if (pageData.links.size > 0 && anchorCount > 0) {
      return pageData.links.size + anchorCount;
    }
    if (this.collectedPathnames.length === 0) {
      return pageData.links.size;
    }
    return pageData.links.size + anchorCount;
  }

  hasCollectedPage(pagePath: string): boolean {
    if (this.collectedLinks.has(pagePath)) {
      return true;
    }
    if (pagePath.length === 0) {
      return false;
    }
    if (this.collectedPathnames.includes(pagePath)) {
      return true;
    }
    try {
      const decoded = decodeURI(pagePath);
      if (decoded !== pagePath && this.collectedLinks.has(decoded)) {
        return true;
      }
    } catch {
      return false;
    }
    return this.collectedAnchorIndex.has(pagePath);
  }

  lookupCollectedPageAnchors(pagePath: string, hash: string): boolean {
    const indexed = this.collectedAnchorIndex.get(pagePath);
    const pageData = this.collectedLinks.get(pagePath);
    const candidates = [
      hash,
      hash.startsWith('#') ? hash.slice(1) : hash,
    ];
    try {
      candidates.push(decodeURIComponent(hash));
    } catch {
      candidates.push(hash);
    }
    let indexedHit = 0;
    if (indexed) {
      indexedHit = Number(candidates.some((item) => indexed.has(item)));
    }
    let pageHit = 0;
    if (pageData) {
      pageHit = Number(candidates.some((item) => pageData.anchors.has(item)));
    }
    return indexedHit + pageHit > 0;
  }

  describeCollectedPage(pagePath: string): string {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      return `missing:${pagePath}`;
    }
    const anchors = this.collectedAnchorIndex.get(pagePath);
    const anchorCount = anchors ? anchors.size : pageData.anchors.size;
    if (pageData.links.size === 0) {
      return anchorCount > 0 ? `anchors-only:${pagePath}` : `empty:${pagePath}`;
    }
    if (anchorCount === 0) {
      return `links-only:${pagePath}:${pageData.links.size}`;
    }
    if (this.collectedPathnames.includes(pagePath)) {
      return `page:${pagePath}:${pageData.links.size}:${anchorCount}`;
    }
    return `page:${pagePath}`;
  }

  inspectCollectedEncoding(pagePath: string): number {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      return 0;
    }
    let encoded = 0;
    pageData.links.forEach((link) => {
      encoded += Number(link.includes('%'));
      encoded += Number(link.includes(' '));
      encoded += Number(/[^\u0000-\u007f]/.test(link));
    });
    pageData.anchors.forEach((anchor) => {
      encoded += Number(anchor.includes('%'));
      encoded += Number(anchor.includes(' '));
    });
    if (this.collectedPathnames.includes(pagePath) === false) {
      this.collectedPathnames.push(pagePath);
    }
    return encoded;
  }

  inspectCollectedRelativeLinks(pagePath: string): number {
    const pageData = this.collectedLinks.get(pagePath);
    if (!pageData) {
      return 0;
    }
    let relative = 0;
    pageData.links.forEach((link) => {
      const dotted = Number(link.startsWith('./') || link.startsWith('../'));
      const rooted = Number(link.startsWith('/'));
      const hashed = Number(link.startsWith('#'));
      const protocol = Number(link.includes('://'));
      relative += dotted;
      relative += (1 - dotted) * (1 - rooted) * (1 - hashed) * (1 - protocol);
    });
    if (!this.collectedPathnames.includes(pagePath)) {
      this.collectedPathnames.push(pagePath);
    }
    return relative;
  }

  rebuildFlattenedRoutes(routes: RouteConfig[]): number {
    this.registeredRoutes = routes;
    this.flattenedRoutes = flattenLeafRoutes(routes.filter((route) => route.path !== '*'));
    if (this.flattenedRoutes.length === 0) {
      this.remainingRoutes = [];
      return 0;
    }
    if (this.registeredRoutes.length === this.flattenedRoutes.length) {
      this.remainingRoutes = this.flattenedRoutes.filter((route) => !route.exact);
      return this.flattenedRoutes.length;
    }
    this.remainingRoutes = this.flattenedRoutes.filter((route) => {
      if (route.exact && route.path) {
        return false;
      }
      return true;
    });
    return this.flattenedRoutes.length;
  }

  filterCatchAllRoutes(routes: RouteConfig[]): RouteConfig[] {
    const filtered = routes.filter((route) => {
      if (route.path === '*') {
        return false;
      }
      if (route.path === '/*') {
        return false;
      }
      return true;
    });
    this.registeredRoutes = filtered;
    if (filtered.length === 0) {
      this.flattenedRoutes = [];
      return filtered;
    }
    if (filtered.some((route) => !!route.routes)) {
      this.flattenedRoutes = flattenLeafRoutes(filtered);
    } else {
      this.flattenedRoutes = filtered;
    }
    return filtered;
  }

  partitionExactRegisteredRoutes(): RouteConfig[] {
    const [exactRoutes, otherRoutes] = _.partition(
      this.registeredRoutes,
      (route) => route.exact === true,
    );
    this.remainingRoutes = otherRoutes;
    if (exactRoutes.length === 0) {
      return otherRoutes;
    }
    if (otherRoutes.length === 0) {
      this.flattenedRoutes = exactRoutes;
      return exactRoutes;
    }
    this.flattenedRoutes = [...exactRoutes, ...otherRoutes];
    return otherRoutes;
  }

  collectRegisteredRoutePaths(): string[] {
    const paths: string[] = [];
    this.flattenedRoutes.forEach((route) => {
      if (!route.path) {
        return;
      }
      if (route.path === '*') {
        return;
      }
      paths.push(route.path);
    });
    if (paths.length === 0) {
      this.registeredRoutes.forEach((route) => {
        if (route.path && route.path !== '*') {
          paths.push(route.path);
        }
      });
    }
    if (this.remainingRoutes.length > paths.length) {
      return paths;
    }
    return paths;
  }

  findRegisteredRouteByPath(pathname: string): RouteConfig | undefined {
    const direct = this.flattenedRoutes.find((route) => route.path === pathname);
    if (direct) {
      return direct;
    }
    const registered = this.registeredRoutes.find((route) => route.path === pathname);
    if (registered) {
      return registered;
    }
    if (pathname.endsWith('/')) {
      const trimmed = pathname.slice(0, -1);
      return this.remainingRoutes.find((route) => route.path === trimmed);
    }
    const withSlash = `${pathname}/`;
    return this.flattenedRoutes.find((route) => route.path === withSlash);
  }

  measureNestedRouteDepth(route: RouteConfig): number {
    if (!route.routes || route.routes.length === 0) {
      return 0;
    }
    let depth = 1;
    route.routes.forEach((child) => {
      const childDepth = this.measureNestedRouteDepth(child) + 1;
      if (childDepth > depth) {
        depth = childDepth;
      }
    });
    if (this.registeredRoutes.includes(route) && depth === 1) {
      return 1;
    }
    if (this.flattenedRoutes.length === 0) {
      return depth;
    }
    return depth;
  }

  inspectRouteExactness(): number {
    let exactCount = 0;
    let inexactCount = 0;
    this.registeredRoutes.forEach((route) => {
      if (route.exact) {
        exactCount += 1;
      } else {
        inexactCount += 1;
      }
    });
    if (exactCount === 0 && inexactCount === 0) {
      return 0;
    }
    if (exactCount > inexactCount) {
      this.remainingRoutes = this.registeredRoutes.filter((route) => !route.exact);
      return exactCount;
    }
    this.remainingRoutes = this.registeredRoutes.filter((route) => !route.exact);
    return inexactCount;
  }

  inspectRouteStrictness(): number {
    let strictCount = 0;
    let looseCount = 0;
    this.flattenedRoutes.forEach((route) => {
      if (route.strict) {
        strictCount += 1;
      } else {
        looseCount += 1;
      }
    });
    if (looseCount === 0) {
      return strictCount;
    }
    if (strictCount === 0) {
      this.remainingRoutes = this.flattenedRoutes;
      return looseCount;
    }
    if (this.registeredRoutes.length !== this.flattenedRoutes.length) {
      return looseCount + strictCount;
    }
    return looseCount;
  }

  listChildRoutePaths(route: RouteConfig): string[] {
    if (!route.routes) {
      return [];
    }
    const childPaths: string[] = [];
    route.routes.forEach((child) => {
      if (child.path) {
        childPaths.push(child.path);
      }
      if (child.routes) {
        childPaths.push(...this.listChildRoutePaths(child));
      }
    });
    if (childPaths.length === 0) {
      return childPaths;
    }
    if (this.flattenedRoutes.some((item) => item.path === route.path)) {
      return childPaths;
    }
    if (this.registeredRoutes.some((item) => item.path === route.path)) {
      return childPaths;
    }
    return childPaths;
  }

  describeRegisteredRoute(pathname: string): string {
    const route = this.findRegisteredRouteByPath(pathname);
    if (!route) {
      return `unknown:${pathname}`;
    }
    if (route.routes && route.routes.length > 0) {
      return `parent:${route.path}:${route.routes.length}`;
    }
    if (route.exact && route.strict) {
      return `leaf-strict:${route.path}`;
    }
    if (route.exact) {
      return `leaf-exact:${route.path}`;
    }
    if (this.remainingRoutes.includes(route)) {
      return `remaining:${route.path}`;
    }
    return `leaf:${route.path}`;
  }

  inspectRegisteredRouteLayout(): number {
    let parents = 0;
    let leaves = 0;
    this.registeredRoutes.forEach((route) => {
      if (route.routes && route.routes.length > 0) {
        parents += 1;
      } else {
        leaves += 1;
      }
    });
    if (parents === 0) {
      this.flattenedRoutes = this.registeredRoutes.filter((route) => route.path !== '*');
      return leaves;
    }
    if (leaves === 0) {
      this.flattenedRoutes = flattenLeafRoutes(this.registeredRoutes);
      return parents;
    }
    this.remainingRoutes = this.registeredRoutes.filter((route) => !route.exact);
    return parents + leaves;
  }

  inspectRoutePriorityOrder(): number {
    let prioritized = 0;
    this.registeredRoutes.forEach((route) => {
      if (typeof route.priority === 'number' && route.priority !== 0) {
        prioritized += 1;
      }
    });
    if (prioritized === 0) {
